import { Components, Theme } from "@mui/material/styles";

const components: Components<Omit<Theme, "components">> = {
  MuiCssBaseline: {
    styleOverrides: {
      body: {
        backgroundColor: "#0A0A0A",
        color: "#FFFFFF",
        WebkitFontSmoothing: "antialiased",
        MozOsxFontSmoothing: "grayscale",
      },
      "*": {
        boxSizing: "border-box",
      },
      "#root": {
        minHeight: "100vh",
      },
    },
  },

  MuiPaper: {
    styleOverrides: {
      root: {
        borderRadius: 4, // Sharp, industrial corners
        backgroundImage: "none",
        backgroundColor: "#1A1A1A",
        border: "1px solid rgba(226, 35, 26, 0.2)",
      },
    },
  },

  MuiCard: {
    defaultProps: {
      elevation: 0,
    },
    styleOverrides: {
      root: {
        borderRadius: 4,
        border: "2px solid rgba(226, 35, 26, 0.3)",
        boxShadow: "0 4px 20px rgba(0, 0, 0, 0.5)",
        overflow: "hidden",
        backgroundColor: "#1A1A1A",
        position: "relative",

        // Eskom red accent stripe
        "&::before": {
          content: '""',
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "4px",
          background: "linear-gradient(90deg, #E2231A 0%, #FF4842 100%)",
        },
      },
    },
  },

  MuiButton: {
    defaultProps: {
      disableElevation: false,
    },
    styleOverrides: {
      root: {
        borderRadius: 4,
        padding: "12px 32px",
        fontWeight: 800,
        minHeight: 48,
        letterSpacing: "0.05em",
        textTransform: "uppercase",
      },

      contained: {
        background: "linear-gradient(135deg, #E2231A 0%, #B01B14 100%)",
        boxShadow: "0 4px 12px rgba(226, 35, 26, 0.4)",

        "&:hover": {
          background: "linear-gradient(135deg, #FF4842 0%, #E2231A 100%)",
          boxShadow: "0 6px 16px rgba(226, 35, 26, 0.6)",
        },
      },

      outlined: {
        borderWidth: 2,
        borderColor: "#E2231A",
        color: "#E2231A",

        "&:hover": {
          borderWidth: 2,
          backgroundColor: "rgba(226, 35, 26, 0.1)",
        },
      },
    },
  },

  MuiOutlinedInput: {
    styleOverrides: {
      root: {
        borderRadius: 4,

        "& fieldset": {
          borderColor: "rgba(255, 255, 255, 0.23)",
          borderWidth: 2,
        },

        "&:hover fieldset": {
          borderColor: "#E2231A",
        },

        "&.Mui-focused fieldset": {
          borderColor: "#E2231A",
          borderWidth: 2,
        },
      },
    },
  },

  MuiTextField: {
    defaultProps: {
      size: "small",
      variant: "outlined",
      fullWidth: true,
    },
  },

  MuiTableContainer: {
    styleOverrides: {
      root: {
        borderRadius: 4,
        border: "2px solid rgba(226, 35, 26, 0.3)",
      },
    },
  },

  MuiTableHead: {
    styleOverrides: {
      root: {
        backgroundColor: "rgba(226, 35, 26, 0.1)",
      },
    },
  },

  MuiTableCell: {
    styleOverrides: {
      head: {
        fontWeight: 800,
        color: "#FFFFFF",
        borderBottom: "2px solid #E2231A",
        textTransform: "uppercase",
        letterSpacing: "0.05em",
        fontSize: "0.8125rem",
      },

      root: {
        paddingTop: 16,
        paddingBottom: 16,
        borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
        color: "#FFFFFF",
      },
    },
  },

  MuiChip: {
    styleOverrides: {
      root: {
        borderRadius: 4,
        fontWeight: 700,
        textTransform: "uppercase",
        letterSpacing: "0.03em",
        fontSize: "0.75rem",
      },
      filled: {
        border: "1px solid currentColor",
      },
    },
  },

  MuiAvatar: {
    styleOverrides: {
      root: {
        fontWeight: 800,
        backgroundColor: "#E2231A",
      },
    },
  },

  MuiDivider: {
    styleOverrides: {
      root: {
        borderColor: "rgba(226, 35, 26, 0.2)",
        borderWidth: 1,
      },
    },
  },

  MuiTooltip: {
    styleOverrides: {
      tooltip: {
        borderRadius: 4,
        fontSize: "0.8125rem",
        backgroundColor: "#1A1A1A",
        border: "1px solid rgba(226, 35, 26, 0.5)",
        fontWeight: 600,
      },
    },
  },

  MuiDialog: {
    styleOverrides: {
      paper: {
        borderRadius: 4,
        border: "2px solid rgba(226, 35, 26, 0.5)",
      },
    },
  },

  MuiDrawer: {
    styleOverrides: {
      paper: {
        border: "none",
        backgroundColor: "#0A0A0A",
      },
    },
  },

  MuiListItemButton: {
    styleOverrides: {
      root: {
        borderRadius: 4,

        "&.Mui-selected": {
          backgroundColor: "rgba(226, 35, 26, 0.2)",
          borderLeft: "4px solid #E2231A",

          "&:hover": {
            backgroundColor: "rgba(226, 35, 26, 0.3)",
          },
        },

        "&:hover": {
          backgroundColor: "rgba(255, 255, 255, 0.05)",
        },
      },
    },
  },
};

export default components;
